ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns mdm http://www.etb.com.co/Gateway/MDM_Logic_Services
---
soapenv#Envelope: {
   soapenv#Header: null,
   soapenv#Body: {
      mdm#OSM_OFSC_Message: {
         mdm#WSRequestHeader: {
            mdm#system: {
               mdm#name: attributes.headers.name,
               mdm#correlationId: attributes.headers.'x-correlation-id',
               mdm#processingServer: attributes.headers.source
            }
         },
         mdm#WSRequestBody: {
            mdm#OrderId: payload.PeticionOutboundETAdirect.EncabezadoMensaje.IdOrdenETAdirect,
            mdm#MessageId: payload.PeticionOutboundETAdirect.EncabezadoMensaje.IdMensaje,
            mdm#RequestDate: payload.PeticionOutboundETAdirect.EncabezadoMensaje.FechaPeticion,
            mdm#RequestType: payload.PeticionOutboundETAdirect.DetalleMensaje.TipoPeticion,
            mdm#Message: if (!payload.Message?) write(payload, 'text/xml') else payload.Message,
         }
      }
   }
}
